/**
 * Palette data types (architecture contract 2). The JSON files in ./data are generated by
 * scripts/drawio-palettes/extract-palettes.ts from jgraph/drawio v32.4.1 (Apache-2.0).
 */

/** Ids of the generated draw.io palettes, in draw.io sidebar order. */
export type DrawioPaletteId = 'general' | 'misc' | 'advanced' | 'basic' | 'arrows2' | 'flowchart' | 'arrows';

/**
 * How the entry's shape is rendered:
 * a = maxGraph core shape, b = draw.io stencil (public/stencils/*.xml),
 * c = JS-implemented draw.io shape (Shapes.js / shapes/mx*.js port),
 * d = other mechanism (edge, text, image, swimlane/container, composite cells, compressed data).
 */
export type PaletteEntryClass = 'a' | 'b' | 'c' | 'd';

export interface PaletteEntry {
  /** Stable slug: <palette>-<index>-<slug(title)>. */
  id: string;
  /** draw.io title (tooltip / search). */
  title: string;
  /** draw.io search tags, as Sidebar.addEntry receives them. */
  tags?: string;
  /** vertex/edge: a single cell built from style/value/size; cells: insert `xml`. */
  kind: 'vertex' | 'edge' | 'cells';
  width: number;
  height: number;
  /** Cell style (vertex/edge entries), byte-for-byte as in draw.io. */
  style?: string;
  /** Cell value/label (vertex/edge entries); omitted when empty. */
  value?: string;
  /** mxGraphModel XML (cells entries: composite cells or decompressed data entries). */
  xml?: string;
  /** All shape names the entry uses (shape= values and shape-selecting named styles). */
  shapeNames: string[];
  cls: PaletteEntryClass;
  /** draw.io source location, relative to src/main/webapp: 'file:line'. */
  source: string;
}

export interface PaletteDef {
  id: string;
  title: string;
  drawioTag: string;
  /** draw.io source of the palette function, e.g. "js/grapheditor/Sidebar.js:2790". */
  source: string;
  entries: PaletteEntry[];
}

export interface PaletteMeta {
  id: string;
  title: string;
  defaultVisible: boolean;
}

/** A palette of the generated catalogue (data/catalogue.json). */
export interface CataloguePalette {
  id: string;
  /** data/<file>.json */
  file: string;
  title: string;
  /** Library ("More shapes" entry) the palette belongs to. */
  library: string;
  count: number;
  /** JS shape names / stencil packages the entries use (for preloading). */
  jsShapes: string[];
  stencils: string[];
}

/** A draw.io library ("More shapes" entry): one or more palettes. */
export interface CatalogueLibrary {
  id: string;
  title: string;
  palettes: string[];
  count: number;
  /** Third-party notice file under third_party/drawio-libraries/ (vendor icon sets). */
  notice?: string;
  /** Short attribution / trademark note shown in the library info. */
  attribution?: string;
  /** True when the icons are fixed-colour vendor artwork (not recoloured in dark mode). */
  vendorIcons?: boolean;
}

export interface PaletteCatalogue {
  drawioTag: string;
  /** draw.io's MoreShapesDialog sections (Standard, Software, Networking, Business, Other). */
  categories: Array<{ title: string; libraries: Array<{ id: string; title: string }> }>;
  libraries: CatalogueLibrary[];
  palettes: CataloguePalette[];
}

/** Search index: per palette, `title\ttags` of every entry in entry order. */
export interface PaletteSearchIndex {
  drawioTag: string;
  palettes: Array<[string, string[]]>;
}
